      "role": "protagonist",
      "identity": "市公安局刑侦支队副队长",
      "traits": ["冷静理性", "执着坚韧", "责任感强", "隐藏脆弱"],
      "overt_motivation": "在12小时内破解系统预言，阻止未婚妻'杀害'自己",
